const data = fs.readFileSync(0, 'utf8');
let idx = 0;

function nextInt() {
    while (idx < data.length && data.charCodeAt(idx) <= 32) idx++;
    let num = 0;
    while (idx < data.length && data.charCodeAt(idx) > 32) {
        num = num * 10 + (data.charCodeAt(idx) - 48);
        idx++;
    }
    return num;
}

const n = nextInt();
